  "legend_alias": "def legend_alias(source):\n    key = str(source)\n    return next(\n        (\n            item[\"text\"]\n            for item in RUN_REPORT[\"spec\"][\"legend\"].get(\"labels\", [])\n            if item[\"series\"] == key\n        ),\n        key,\n    )",
